//! Compatibility and corruption checks are separate from executable trust.
use crate::ScriptError;
use sha2::{Digest, Sha256};

pub const ARTIFACT_FORMAT: u32 = 1;
pub const ENGINE_VERSION: &str = "rquickjs-0.14.0/quickjs-ng-0.16.2/bytecode-28";
pub const BUILD_ID: &str = env!("INCANT_SCRIPT_BUILD_ID");
pub const TARGET: &str = env!("INCANT_SCRIPT_TARGET");
pub const MAX_BYTECODE_BYTES: usize = 4 * 1024 * 1024;
pub const MAX_SOURCE_BYTES: usize = 1_000_000;
pub const WRAPPER_PREFIX_LINES: u32 = 3;

/// Generated by the trusted cook. Names and hashes support diagnostics and
/// integrity; none of these fields authenticate executable bytes.
#[derive(Clone, Debug)]
pub struct ScriptMetadata {
    pub format: u32,
    pub engine: String,
    pub build_id: String,
    pub target: String,
    pub source_name: String,
    pub source_sha256: [u8; 32],
    pub wrapper_prefix_lines: u32,
    pub bytecode_sha256: [u8; 32],
    pub hardening_sha256: [u8; 32],
}

/// An embedded build product, never a project/cache/mod/network file format.
/// Constructing this descriptor does not authorize QuickJS to read the bytes.
pub struct EmbeddedScript {
    pub metadata: ScriptMetadata,
    pub bytecode: &'static [u8],
    pub hardening: &'static [u8],
}

pub(crate) fn digest(bytes: &[u8]) -> [u8; 32] {
    Sha256::digest(bytes).into()
}

pub(crate) fn valid_name(name: &str) -> bool {
    !name.is_empty() && name.len() <= 256 && !name.chars().any(char::is_control)
}

pub(crate) fn validate(
    metadata: &ScriptMetadata,
    bytecode: &[u8],
    hardening: &[u8],
) -> Result<(), ScriptError> {
    if metadata.format != ARTIFACT_FORMAT
        || metadata.engine != ENGINE_VERSION
        || metadata.build_id != BUILD_ID
        || metadata.target != TARGET
        || metadata.wrapper_prefix_lines != WRAPPER_PREFIX_LINES
    {
        return Err(ScriptError::ArtifactCompatibility);
    }
    if !valid_name(&metadata.source_name)
        || bytecode.is_empty()
        || hardening.is_empty()
        || bytecode.len() > MAX_BYTECODE_BYTES
        || hardening.len() > MAX_BYTECODE_BYTES
    {
        return Err(ScriptError::InputLimit);
    }
    if digest(bytecode) != metadata.bytecode_sha256
        || digest(hardening) != metadata.hardening_sha256
    {
        return Err(ScriptError::ArtifactIntegrity);
    }
    Ok(())
}

#[cfg(all(test, feature = "compiler"))]
mod tests {
    use super::*;
    use crate::{CompiledScript, EmbeddedScript, ScriptHost};

    fn compiled(source: &str) -> CompiledScript {
        CompiledScript::compile_named("fixture.js", source).unwrap()
    }

    fn embedded(code: CompiledScript) -> CompiledScript {
        let artifact = EmbeddedScript {
            metadata: code.metadata.clone(),
            bytecode: Box::leak(code.bytes.to_vec().into_boxed_slice()),
            hardening: Box::leak(code.hardening.to_vec().into_boxed_slice()),
        };
        // SAFETY: test uses unchanged output from the identical local compiler,
        // including its fixed hardening module. No forged bytes enter QuickJS.
        unsafe { CompiledScript::from_embedded(artifact) }.unwrap()
    }

    #[test]
    fn compatibility_and_corruption_fail_without_reading_quickjs_bytecode() {
        let code = compiled("exports.default = {update() {}};");
        for change in 0..5 {
            let mut m = code.metadata.clone();
            match change {
                0 => m.format += 1,
                1 => m.engine.push_str("-wrong"),
                2 => m.target.push_str("-wrong"),
                3 => m.build_id.push_str("-wrong"),
                _ => m.wrapper_prefix_lines += 1,
            }
            assert!(matches!(
                validate(&m, &code.bytes, &code.hardening),
                Err(ScriptError::ArtifactCompatibility)
            ));
        }
        for hardening in [false, true] {
            let mut bytes = code.bytes.to_vec();
            let mut fixed = code.hardening.to_vec();
            if hardening {
                fixed[0] ^= 1;
            } else {
                bytes[0] ^= 1;
            }
            assert!(matches!(
                validate(&code.metadata, &bytes, &fixed),
                Err(ScriptError::ArtifactIntegrity)
            ));
        }
        assert!(matches!(
            validate(&code.metadata, &[], &code.hardening),
            Err(ScriptError::InputLimit)
        ));
        assert!(matches!(
            validate(
                &code.metadata,
                &vec![0; MAX_BYTECODE_BYTES + 1],
                &code.hardening
            ),
            Err(ScriptError::InputLimit)
        ));
        // A caller can forge matching hashes; that is precisely why validation
        // is NOT a public safe bytecode loader. Never give this to QuickJS.
        let mut forged = code.metadata.clone();
        forged.bytecode_sha256 = digest(b"not bytecode");
        assert!(validate(&forged, b"not bytecode", &code.hardening).is_ok());
    }

    #[test]
    fn embedded_module_executes_without_eval_and_keeps_transfer_hardening() {
        let code = embedded(compiled(
            r#"
            for (const compile of [
                () => eval('1'),
                () => (0,eval)('1'),
                () => Function('return 1'),
                () => (function(){}).constructor('return 1'),
                () => (async function(){}).constructor('return 1'),
                () => (function*(){}).constructor('yield 1'),
            ]) {
                let rejected = false;
                try { compile(); } catch (_) { rejected = true; }
                if (!rejected) throw Error('runtime source compiler active');
            }
            exports.default = { update({chunks, dt}) {
                if (globalThis.old && old.byteLength !== 0) throw Error('retained loan');
                globalThis.old = chunks[0].transforms;
                for (const c of chunks) c.transforms[0] += dt;
                for (const name of ['transfer','transferToFixedLength','transferToImmutable']) {
                    let rejected = false;
                    try { old.buffer[name](); } catch (_) { rejected = true; }
                    if (!rejected) throw Error('transfer enabled');
                }
            }};
        "#,
        ));
        let mut host = ScriptHost::new(code).unwrap();
        let mut world = crate::tests::world();
        for _ in 0..3 {
            host.tick(&mut world, 0.25).unwrap();
        }
        assert_eq!(
            world
                .inspect(crate::tests::id(1))
                .unwrap()
                .transform
                .translation[0],
            0.75
        );
    }

    #[test]
    fn embedded_failure_and_deferred_work_still_roll_back() {
        for operation in [
            "throw Error('late')",
            "void new Promise(() => {})",
            "eval('1')",
            "new ArrayBuffer(64 * 1024 * 1024)",
            "for (;;) {}",
        ] {
            let code = embedded(compiled(&format!(
                "exports.default = {{update({{chunks}}) {{chunks[0].transforms[0] = 99; {operation};}}}};"
            )));
            let mut host = ScriptHost::new(code).unwrap();
            let mut world = crate::tests::world();
            let before = world.snapshot();
            assert!(host.tick(&mut world, 0.25).is_err());
            assert_eq!(world.snapshot(), before);
            assert!(matches!(
                host.tick(&mut world, 0.25),
                Err(ScriptError::FailedSession)
            ));
        }
        let code = embedded(compiled(
            "void new Promise(() => {}); exports.default = {update(){}};",
        ));
        assert!(matches!(
            ScriptHost::new(code),
            Err(ScriptError::UnsupportedAsync)
        ));
    }

    #[test]
    fn source_is_stripped_but_module_identity_remains_in_bytecode() {
        let marker = "UNIQUE_SOURCE_COMMENT_NOT_EMBEDDED_72a";
        let code = compiled(&format!(
            "// {marker}\nexports.default = {{update() {{}}}};"
        ));
        assert!(
            !code
                .bytes
                .windows(marker.len())
                .any(|w| w == marker.as_bytes())
        );
        assert!(
            code.bytes
                .windows("fixture.js".len())
                .any(|w| w == b"fixture.js")
        );
        assert_eq!(code.metadata.wrapper_prefix_lines, 3);
    }
}
